$().ready(function(){
    
    loadDate();
    var solicitudPrestamo = "";
    var rutaSolicitud = "";
    var rutaIFE = "";
    var rutaDomicilio = "";
    var rutaTalon = "";
    var rutaCLABE = "";
    var zonaTrabajo = $("#hiddenZonaTrabajo").val().trim().toUpperCase();

    $("#slctEntFederativa option").each(function () {
        if ($(this).text().trim().toUpperCase() === zonaTrabajo) {
            $(this).prop("selected", true);
        }
    });
    
    $("#formEnviarSolicitud").hide();
    $("#formCargarIFE").hide();
    $("#formCargarDomicilio").hide();
    $("#formCargarTalonPago").hide();
    $("#formCargarClabe").hide();
    $("#EnviarSolicitud").hide();
    
    $("#btnCancelar").click(function(){
        var url="PortalSecretarios.php";
        $(location).attr('href',url);
    });
    
    $("#btnGeneraSolicitud").click(function(){
        var arrayErrores = [];
        $("#resDatos").empty();
        
        var resultado = validaInfo(arrayErrores);
        
        if(!resultado){
            $.each(arrayErrores,function(index,value){
                var spanError = document.createElement("span");
                $spanError = $(spanError);
                $spanError.html(value);
                $spanError.addClass("errorValidacion");
                $("#resDatos").append($spanError).append(document.createElement("br"));
            });
        } else {
                var datosPersonalesSolicitud;
                var datosLaboralesSolicitud;
                var datosDomiciloSolicitud;
                
                try{
                    
                   var anio = new Date().getFullYear();
                   //var entidad = $("#slctEntFederativa").val();
                   var entidad = $("#hiddenCodigoSeccion").val();
                   var folioNumerico = $("#hiddenFolio").val();
                   var folio4Digitos = folioNumerico.padStart(4,'0');

                   var folioFinal = anio + '/' + entidad + '/' + folio4Digitos;

                   datosPersonalesSolicitud = new DatosPersonales($("#txtApPatEmp").val(),$("#txtApMatEmp").val(), $("#txtNombreEmp").val(), $("#txtRfcEmp").val());
                   datosLaboralesSolicitud = new DatosLaborales($("#fechaIngreso").val(),$("#txtPuesto").val(),$("#txtCodigNum").val(),$("#txtOficina").val(),$("#txtEstadoEmp").val());
                   datosDomicilioSolicitud = new DatosDomiciliarios($("#txtCalle").val(), $("#txtNumExt").val(), $("#txtNumInt").val(), $("#txtTelefono").val(), $("#txtColonia").val(), $("#txtCodPostal").val(), $("#txtDelMun").val(), $("#txtEntFed").val());
                   //alexo cambiar aqui el hiddenfolio 
                   solicitudPrestamo = new Solicitud(folioFinal, $("#fechaSolicitud").val(), $("#slctEntFederativa option:selected").text(), datosPersonalesSolicitud, datosLaboralesSolicitud, datosDomicilioSolicitud, $("#txtClabe").val(), $("#txtBanco").val(), $("input:radio[name=rBtnMonto]:checked").val() + "_" + $("#slctEntFederativa").val() + "_" + $("#txtArComentarios").val());
                   
                   crearPDF(solicitudPrestamo, $("input:radio[name=rBtnMonto]:checked").val());
                   $("#formEnviarSolicitud").show();
                   $("#formCargarIFE").show();
                   $("#formCargarDomicilio").show();
                   $("#formCargarTalonPago").show();
                   $("#formCargarClabe").show();
                   $("#formSolicitud :input").attr("disabled", true);
                   $("#EnviarSolicitud").show();
                   $("#BtnEnviarSolicitudPrestamos").focus();
                } catch(e){
                alert("Ocurrio un error: " + e.message);
            }
        }
    });
    
    
    $("#BtnEnviarSolicitudPrestamos").click(function(){
        
        if($("#fileSelSolicitud").val() != "" && $("#rfcImageFile") != "" && $("#domicilioFile") !="" && $("#talonFile") != "" && $("#clabeFile") != ""){
            var formDataRequest = new FormData();

            var pdfRequest = $("#fileSelSolicitud").prop('files')[0];
            var imgIfe = $("#rfcImageFile").prop('files')[0];
            var imgAddress = $("#domicilioFile").prop('files')[0];
            var imgCheck = $("#talonFile").prop('files')[0];
            var imgClabe = $("#clabeFile").prop('files')[0];

            var jsonSend = JSON.stringify(solicitudPrestamo);

            formDataRequest.append('requestFile', pdfRequest);
            formDataRequest.append('ifeFile', imgIfe);
            formDataRequest.append('addressFile', imgAddress);
            formDataRequest.append('checkFile', imgCheck);
            formDataRequest.append('clabeFile', imgClabe);

            formDataRequest.append('rFCEmpleado', solicitudPrestamo.datosPersonales.rFC);
            formDataRequest.append('folioSolicitud', solicitudPrestamo.folio);
            formDataRequest.append('jsonTest', jsonSend);

            $.ajax({
                url: 'libs/requestLoader.php',
                dataType: 'text',
                cache: false,
                contentType: false,
                processData: false,
                data: formDataRequest,
                type: 'post',
                success: function(data){
                    alert("La solicitud ha sido correctamente enviada al área de préstamos. " + data);
                    //$("#modalExito").modal();
                    window.location.replace('PortalSecretarios.php');
                },
                error: function(xhr, status, error){
                    alert(xhr.responseText);
                }
            });
        } else {
            //alert("Verifica que todas las imagenes se encuentren correctamente seleccionadas.");
            $("#modalCarga").modal();
        }
    });
    
});

function validaInfo(arrayErrores){
    
    if(!validaSoloLetrasObligatorio($("#txtNombreEmp").val().trim())){
        arrayErrores.push("El Nombre del empleado no es válido. Debe estar formado únicamente por letras.");
    }
    
    if(!validaSoloLetrasObligatorio($("#txtApPatEmp").val().trim())){
        arrayErrores.push("El Apellido paterno del empleado no es válido. Debe estar formado únicamente por letras");
    }
    
    if(!validaSoloLetrasObligatorio($("#txtApMatEmp").val().trim())){
        arrayErrores.push("El Apellido materno del empleado no es válido. Debe estar formado únicamente por letras");
    }
    
    if(!validaRFC($("#txtRfcEmp").val().trim())){
        arrayErrores.push("El RFC no es válido. Asegurate que tenga el formato correcto.");
    }
    
    if(!validaOracion($("#txtPuesto").val().trim())){
        arrayErrores.push("El puesto no es válido.");
    }
    
    if(!validaOracion($("#txtCodigNum").val().trim())){
        arrayErrores.push("El valor del Código y Número Análitico no es válido.");
    }
    
    if(!validaOracion($("#txtOficina").val().trim())){
        arrayErrores.push("La oficina no es válida.");
    }
    
    if(!validaSoloLetrasObligatorio($("#txtEstadoEmp").val().trim())){
        arrayErrores.push("La ciudad y Entidad federativa no es válida.");
    }
    
    if(!validaOracion($("#txtCalle").val().trim())){
        arrayErrores.push("La calle no es válida.");
    }
    
    if(!validaOracion($("#txtNumExt").val().trim())){
        arrayErrores.push("El número exterior no es válido.");
    }
    
    if(!validaOracion($("#txtNumInt").val().trim())){
        arrayErrores.push("El número interior no es válido.");
    }
    
    if(!validaTelefono($("#txtTelefono").val().trim())){
        arrayErrores.push("El número telefonico no es válido.");
    }
    
    if(!validaOracion($("#txtColonia").val().trim())){
        arrayErrores.push("La colonia no es válida.");
    }
    
    if(!validaSoloNumerosObligatorio($("#txtCodPostal").val().trim())){
        arrayErrores.push("El código postal no es válido.");
    }
    
    if(!validaSoloLetrasObligatorio($("#txtDelMun").val().trim())){
        arrayErrores.push("La delegación/municipio no es válida(o).");
    }
    
    if(!validaSoloLetrasObligatorio($("#txtEntFed").val().trim())){
        arrayErrores.push("La entidad federativa no es válida.");
    }
    
    if(!validaSoloNumerosObligatorio($("#txtClabe").val().trim())){
        arrayErrores.push("La clave interbancaria (CLABE) no es válida.");
    }
    
    if(!validaSoloLetrasObligatorio($("#txtBanco").val().trim())){
        arrayErrores.push("El banco no es válido.");
    }
    
    if(!validaOracion($("#txtArComentarios").val().trim())){
        arrayErrores.push("Existen caracteres no válidos en la caja de comentarios");
    }
    
    if(arrayErrores.length > 0){
        return false;
    } else {
        return true;
    }
}

function validaSoloLetrasObligatorio(textValue){
    var regex = new RegExp(/^[a-zA-ZñÑ ]+$/);

    if(textValue === ""){
        return false;
    } else if(regex.test(textValue)){
        return true;
    } else {
        return false;
    }
}

function validaSoloNumerosObligatorio(textValue){
    var regex = new RegExp(/^[0-9 ]+$/);
     
    if(textValue === "" ){
        return false;
    } else if(regex.test(textValue)){
        return true;
    } else {
        return false;
    }
}

function validaSoloLetras(textValue){
    var regex = new RegExp(/^[a-zA-ZñÑ ]+$/);
     
    if(textValue === "" ){
        return true;
    } else if(regex.test(textValue)){
        return true;
    } else {
        return false;
    }
}

function validaSoloNumeros(textValue){
    var regex = new RegExp(/^[0-9 ]+$/);
     
    if(textValue === "" ){
        return true;
    } else if(regex.test(textValue)){
        return true;
    } else {
        return false;
    }
}

function validaRFC(textValue){
    var regex = new RegExp(/^[0-9A-Za-zñÑ]+$/);
    
    if(textValue === "" ){
        return false;
    } else if(regex.test(textValue)){
        return true;
    } else {
        return false;
    }
}

function validaOracion(textValue){
    var regex = new RegExp(/^[0-9A-Za-zñÑ @-áéíóúÁÉÍÓÚ.,/]+$/);
    
    if(textValue === "" ){
        return true;
    } else if(regex.test(textValue)){
        return true;
    } else {
        return false;
    }
}

function validaTelefono(textValue){
    var regex = new RegExp(/^[0-9-]+$/);
    
    if(textValue === "" ){
        return false;
    } else if(regex.test(textValue)){
        return true;
    } else {
        return false;
    }
}

function crearPDF(solicitudDePrestamo, montoPrestamo){

    console.log(montoPrestamo);

    var imageData;
    
    switch(montoPrestamo){
        case "10000" :
            //ok
            imageData = "data:image/jpeg;base64,";
        break;
        case "15000" :
            imageData = "data:image/jpeg;base64,";
        break;
        case "18000" :
            imageData = "data:image/jpeg;base64,";
        break;
        case "20000" :
            imageData = "data:image/jpeg;base64,";
        break;
        default:
            imageData = "data:image/jpeg;base64,";
        break;
    }
    
    var doc = new jsPDF();
    doc.addImage(imageData,'JPEG',0,0);
    doc.setFontSize(11);
    doc.text(160,26, solicitudDePrestamo.folio); //Folio
    doc.setFontSize(9);
    doc.text(46,54, solicitudDePrestamo.entidadFedeSol); //Entidad Federativa
    doc.text(164,54, solicitudDePrestamo.getDiaSolicitud()); //Dia
    doc.text(175,54, solicitudDePrestamo.getMesSolicitud()); //Mes
    doc.text(182,54, solicitudDePrestamo.getAnioSolicitud()); //Año
    doc.text(14,77, solicitudDePrestamo.datosPersonales.apPaterno); //Apellido Paterno
    doc.text(85,77, solicitudDePrestamo.datosPersonales.apMaterno); //Apellido Materno
    doc.text(145,77, solicitudDePrestamo.datosPersonales.nombre); //Nombre 
    doc.text(14,88, solicitudDePrestamo.datosPersonales.rFC); //RFC
    doc.text(162,88, solicitudDePrestamo.datosLaborales.getDiaIngreso()); //Dia Ingreso
    doc.text(171,88, solicitudDePrestamo.datosLaborales.getMesIngreso()); //Mes Ingreso
    doc.text(178,88, solicitudDePrestamo.datosLaborales.getAnioIngreso()); //Año Ingreso
    doc.text(14,100, solicitudDePrestamo.datosLaborales.puesto); //Puesto
    doc.text(120,100, solicitudDePrestamo.datosLaborales.codNumAnalitico); //Codigo y Num Analitico
    doc.text(14,112, solicitudDePrestamo.datosLaborales.oficina); //Oficina donde labora
    doc.text(120,112, solicitudDePrestamo.datosLaborales.ciudadEntidad); //Ciudad y Entidad Federativa
    doc.text(14,131, solicitudDePrestamo.datosDomiciliarios.calle); //Calle
    doc.text(112,131, solicitudDePrestamo.datosDomiciliarios.numExt); //Num Exterior
    doc.text(132,131, solicitudDePrestamo.datosDomiciliarios.numInt); //Num Interior
    doc.text(158,131, solicitudDePrestamo.datosDomiciliarios.telefono); //Telefono
    doc.text(14,141, solicitudDePrestamo.datosDomiciliarios.colonia); //Colonia
    doc.text(78,141, solicitudDePrestamo.datosDomiciliarios.codigoPostal); //Codigo Postal
    doc.text(115,141, solicitudDePrestamo.datosDomiciliarios.delMun); //Delegacion
    doc.text(159,141, solicitudDePrestamo.datosDomiciliarios.EntidadFederativa); //Entidad Federativa
    doc.text(48,180, solicitudDePrestamo.clabe); //Clave Bancaria
    doc.text(138,180, solicitudDePrestamo.banco); //Institucion Bancaria
  //doc.output('datauri');
    doc.save('Sol_' + solicitudDePrestamo.folio.replace(/\//g, '-') + '_' + solicitudDePrestamo.datosPersonales.rFC + ".pdf");
  
}

function loadDate(){
    var date = new Date();

    var day = date.getDate();
    var month = date.getMonth() + 1;
    var year = date.getFullYear();

    if (month < 10) month = "0" + month;
    if (day < 10) day = "0" + day;

    var today = year + "-" + month + "-" + day;       
    $("#fechaSolicitud").attr("value", today);
}
